package com.coraline.tycoon;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.server.level.*;
import net.minecraft.world.level.block.*;
/** Indexed owner furniture plus a bounded walkable-space flood fill, never a whole-world scan. */
public final class TycoonRooms {
    public record Survey(Map<String,List<BlockPos>> furniture,Set<BlockPos> reachable,List<BlockPos> beds,List<String> problems){public int capacity(){return beds.size();}public boolean approved(){return problems.isEmpty();}}
    public static boolean feet(ServerLevel l,BlockPos at){if(!l.hasChunkAt(at)||!l.getFluidState(at).isEmpty()||!l.getFluidState(at.above()).isEmpty())return false;var floor=l.getBlockState(at.below());if(floor.is(Blocks.MAGMA_BLOCK)||floor.is(Blocks.CACTUS)||floor.is(Blocks.CAMPFIRE)||floor.is(Blocks.SOUL_CAMPFIRE))return false;var support=floor.getCollisionShape(l,at.below());if(support.isEmpty()||support.max(Direction.Axis.Y)<.5)return false;for(int dy=0;dy<2;dy++){var p=at.above(dy);var s=l.getBlockState(p);if(s.getBlock() instanceof DoorBlock)continue;var shape=s.getCollisionShape(l,p);if(!shape.isEmpty()&&!(dy==0&&shape.max(Direction.Axis.Y)<=.125))return false;}return true;}
    public static Survey survey(ServerPlayer p){var h=TycoonWorld.home(p);var l=p.server.overworld();var all=new HashMap<String,List<BlockPos>>();var reachable=new HashSet<BlockPos>();var beds=new ArrayList<BlockPos>();var errors=new ArrayList<String>();var entrance=h.entrance();if(entrance==null)return new Survey(all,reachable,beds,List.of("Place your Special Door near your registered bed."));int radius=TycoonConfig.INFLUENCE.get();
        var registered=TycoonWorld.registeredBed(p);if(registered==null||registered.distSqr(entrance)>Math.pow(TycoonConfig.BED_RADIUS.get(),2))errors.add("Restore your registered bed within the Special Door's placement radius before accepting more residents.");
        var start=TycoonWorld.landing(l,entrance);var queue=new ArrayDeque<BlockPos>();if(start!=null){reachable.add(start);queue.add(start);}while(!queue.isEmpty()&&reachable.size()<4096){var at=queue.remove();for(var direction:Direction.Plane.HORIZONTAL)for(int dy:new int[]{0,1,-1}){var next=at.relative(direction).above(dy);if(Math.abs(next.getY()-entrance.getY())>6||next.distSqr(entrance)>radius*radius||reachable.contains(next)||!feet(l,next))continue;reachable.add(next);queue.add(next);break;}}
        var indexed=h.state.getCompound("Furniture");for(String key:new HashSet<>(indexed.getAllKeys())){BlockPos at;try{at=BlockPos.of(Long.parseLong(key));}catch(NumberFormatException bad){continue;}if(at.distSqr(entrance)>radius*radius||!l.hasChunkAt(at)||!(l.getBlockEntity(at) instanceof TycoonBlockEntity be)||!h.owner.equals(be.owner)||!be.kind().equals(indexed.getString(key))||be.getBlockState().getValue(TycoonBlock.BROKEN))continue;boolean access=approach(reachable,at)!=null;if(!access)continue;all.computeIfAbsent(be.kind(),k->new ArrayList<>()).add(at);if(be.kind().equals("orphan_bed")&&safeRoom(l,at,reachable))beds.add(at);}
        if(beds.isEmpty())errors.add("No accessible owned Orphan Bed in a safe, lit room.");for(var entry:Map.of("orphan_food_table","No reachable dining table.","orphan_fridge","No reachable fridge.","water_station","No reachable water station.").entrySet())if(all.getOrDefault(entry.getKey(),List.of()).isEmpty())errors.add(entry.getValue());
        boolean food=all.getOrDefault("orphan_fridge",List.of()).stream().anyMatch(at->{var be=(TycoonBlockEntity)l.getBlockEntity(at);for(int i=0;i<be.getContainerSize();i++)if(TycoonBlockEntity.food(be.getItem(i)))return true;return false;});if(!food)errors.add("Stock the fridge with edible food.");if(all.getOrDefault("water_station",List.of()).stream().noneMatch(at->((TycoonBlockEntity)l.getBlockEntity(at)).water>0))errors.add("Refill the water station with a water bucket.");if(beds.size()<h.activeResidents())errors.add("Residents outnumber valid beds; restore facilities before the next inspection.");return new Survey(all,reachable,beds,errors);
    }
    public static BlockPos approach(Set<BlockPos> reachable,BlockPos object){return object==null?null:reachable.stream().filter(p->Math.abs(p.getY()-object.getY())<=1&&p.distSqr(object)<=3).min(Comparator.comparingDouble(p->p.distSqr(object))).orElse(null);}
    public static boolean safeRoom(ServerLevel l,BlockPos bed,Set<BlockPos> reachable){if(approach(reachable,bed)==null||l.getMaxLocalRawBrightness(bed.above())<4)return false;boolean roof=false;for(int y=2;y<=6;y++)if(l.getBlockState(bed.above(y)).isSolidRender(l,bed.above(y))){roof=true;break;}return roof&&reachable.stream().filter(p->p.distSqr(bed)<16).count()>=4;}
    public static int comfort(ServerPlayer p,TycoonData.Resident child,Survey survey){if(child.bed()==null||!survey.beds.contains(child.bed()))return 0;int comfort=35;for(String id:List.of("orphan_rug","orphan_lamp","orphan_plant","toy_box","storage_cabinet")){long count=survey.furniture.getOrDefault(id,List.of()).stream().filter(at->at.distSqr(child.bed())<=36).count();comfort+=count>0?10:0;if(count>1)comfort+=2;}return Math.min(100,comfort);}
}
